class Solution {
 int R,C,food,cj,mj;vector<string> board;vector<vector<int>> movesM,movesC;
 vector<signed char> memo;int P;
 vector<vector<int>> build(int jump){
  vector<vector<int>> moves(P);const int dr[4]={1,-1,0,0},dc[4]={0,0,1,-1};
  for(int p=0;p<P;++p){int r=p/C,c=p%C;if(board[r][c]=='#')continue;
   moves[p].push_back(p);
   for(int d=0;d<4;++d)for(int k=1;k<=jump;++k){int nr=r+dr[d]*k,nc=c+dc[d]*k;
    if(nr<0||nr>=R||nc<0||nc>=C||board[nr][nc]=='#')break;
    moves[p].push_back(nr*C+nc);
   }
  }return moves;
 }
 bool win(int m,int c,int t){
  if(m==c||c==food)return false;
  if(m==food)return true;
  if(t==1000)return false;
  int idx=(t*P+m)*P+c;
  if(memo[idx]!=-1)return memo[idx];
  if(t%2==0){for(int nm:movesM[m])if(win(nm,c,t+1))return memo[idx]=1;return memo[idx]=0;}
  for(int nc:movesC[c])if(!win(m,nc,t+1))return memo[idx]=0;
  return memo[idx]=1;
 }
public:
 bool canMouseWin(vector<string>& grid,int catJump,int mouseJump){
  board=grid;R=grid.size();C=grid[0].size();P=R*C;cj=catJump;mj=mouseJump;
  int m=0,c=0;for(int i=0;i<R;++i)for(int j=0;j<C;++j){
   if(grid[i][j]=='M')m=i*C+j;
   if(grid[i][j]=='C')c=i*C+j;
   if(grid[i][j]=='F')food=i*C+j;
  }
  movesM=build(mj);movesC=build(cj);
  memo.assign(1000*P*P,-1);return win(m,c,0);
 }
};
